USE os_base_sysadmin;
SET NAMES utf8mb4;

-- 此版本迁移仅执行一次。DATETIME 不进行时区转换；历史记录已截断的毫秒无法恢复。
ALTER TABLE base_sys_internal_message MODIFY COLUMN created_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间', MODIFY COLUMN updated_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间';
ALTER TABLE base_sys_internal_message_recipient MODIFY COLUMN created_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间', MODIFY COLUMN updated_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间';
